import java.util.*;
public class ColumnarTransposition {public static void main(String[]z){Scanner sc=new Scanner(System.in);System.out.print("Enter plaintext: ");String p=sc.nextLine().replace(" ","");System.out.print("Enter key: ");String key=sc.nextLine();if(key.isEmpty()){System.out.println("Key cannot be empty.");return;}int k=key.length();while(p.length()%k!=0)p+="X";int rows=p.length()/k;Integer[] order=new Integer[k];for(int i=0;i<k;i++)order[i]=i;Arrays.sort(order,Comparator.comparingInt((Integer i)->key.charAt(i)).thenComparingInt(i->i));StringBuilder ct=new StringBuilder();for(int col:order)for(int row=0;row<rows;row++)ct.append(p.charAt(row*k+col));char[][] cols=new char[k][rows];int idx=0;for(int col:order)for(int row=0;row<rows;row++)cols[col][row]=ct.charAt(idx++);StringBuilder dt=new StringBuilder();for(int row=0;row<rows;row++)for(int col=0;col<k;col++)dt.append(cols[col][row]);System.out.println("Ciphertext: "+ct);System.out.println("Decrypted: "+dt);}}
